=== .devcontainer/devcontainer.json ===
{
    "name": "atmosphera-hub",

    // Riusa il docker-compose.yaml esistente (nessuna duplicazione della config).
    "dockerComposeFile": [
        "../docker-compose.yaml"
    ],

    // Il container PHP (php:8.5-fpm) è quello su cui si lavora.
    "service": "web",

    // Stessa working_dir definita nel compose / dockerfile.
    "workspaceFolder": "/var/www",

    // I servizi nel compose non hanno depends_on: senza questo elenco
    // verrebbe avviato solo "web". Qui li avviamo tutti.
    "runServices": [
        "web",
        "nginx",
        "db",
        "phpmyadmin",
        "node",
        "smtp"
    ],

    // Utente "www" creato nel dockerfile (uid da COMPOSE_WEB_RUN_USER=1000):
    // mantiene i permessi dei file allineati all'host.
    "remoteUser": "www",

    // Chiudendo VS Code ferma l'intero stack compose.
    "shutdownAction": "stopCompose",

    "customizations": {
        "vscode": {
            "extensions": [
                "bmewburn.vscode-intelephense-client",
                "xdebug.php-debug",
                "junstyle.php-cs-fixer",
                "SanderRonde.phpstan-vscode",
                "bradlc.vscode-tailwindcss",
                "EditorConfig.EditorConfig",
                "laravel.vscode-laravel",
                "shufo.vscode-blade-formatter",
                "amiralizadeh9480.laravel-extra-intellisense",
                "onecentlin.laravel-blade",
                "nhoizey.gremlins",
                "sst-dev.opencode"
            ],
            "settings": {
                // php-cs-fixer come formatter del PHP, eseguito al salvataggio sul file in editing.
                // Path ASSOLUTI (non ${workspaceFolder}): in un workspace multi-root quella variabile
                // si risolverebbe alla root del file (es. /var/digital-hub, che non ha vendor/ né config).
                // digital-hub viene formattato con la config di atmosphera (che include ../digital-hub/src).
                "php-cs-fixer.executablePath": "/var/www/vendor/bin/php-cs-fixer",
                "php-cs-fixer.config": "/var/www/.php-cs-fixer.dist.php",
                "php-cs-fixer.formatHtml": false,
                "php-cs-fixer.allowRisky": true,
                "[php]": {
                    "editor.defaultFormatter": "junstyle.php-cs-fixer",
                    "editor.formatOnSave": true
                }
            }
        }
    },

    // Imposto alcuni alias utili nel container, recuperandoli da aliases.sh (.devcontainer/aliases.sh) dal ~/.bashrc.
    // Idempotente: aggiunge la riga solo se non già presente.
    "postCreateCommand": "grep -qxF 'source /var/www/.devcontainer/aliases.sh' ~/.bashrc || echo 'source /var/www/.devcontainer/aliases.sh' >> ~/.bashrc",

    // Ad ogni avvio del container avvia php-fpm (entrypoint = "sleep infinity", quindi non parte da solo).
    // Gira come www (uid 1000): i worker girano come www anziché www-data, ok per i permessi sui file montati.
    // -D daemonizza: il comando ritorna subito e non blocca l'avvio. Equivale all'alias "fpm".
    "postStartCommand": "php-fpm -D"

    // composer/npm install: il container monta ./ quindi vendor/ e node_modules/
    // dell'host sono già disponibili. Se servisse rigenerarli, NON aggiungere un secondo
    // postCreateCommand: concatenare al comando sopra, es. "... >> ~/.bashrc && composer install".
}

=== .vscode/extensions.json ===
{
    "recommendations": []
}

