pkg=$(find ~/.vscode*/extensions ~/.vscode-server*/extensions -maxdepth 1 -iname "sanderronde.phpstan-vscode*" 2>/dev/null | head -1); echo "EXT: $pkg"; [ -n "$pkg" ] && python3 -c "
import json,sys
d=json.load(open('$pkg/package.json'))
props=d['contributes']['configuration']
if isinstance(props,list):
    merged={}
    [merged.update(p.get('properties',{})) for p in props]
    props=merged
else:
    props=props['properties']
for k,v in props.items():
    if k.startswith('phpstan.'):
        print(f\"{v.get('scope','window'):18} {k}\")
"
